<script lang="ts">
  import { Dialog, Tabs } from "bits-ui"; import { jsonStore } from "@slop/svelte"; import Check from "@lucide/svelte/icons/check"; import Plus from "@lucide/svelte/icons/plus"; import X from "@lucide/svelte/icons/x";
  type Item={id:number;text:string;done?:boolean};type Action=Item&{owner:string};type Meeting={title:string;date:string;attendees:string;summary:string;agenda:Item[];decisions:Item[];actions:Action[];nextID:number};
  const meeting=jsonStore<Meeting>("state",{title:"Meeting",date:"",attendees:"",summary:"",agenda:[],decisions:[],actions:[],nextID:1});let tab=$state("notes");let adding=$state(false);let text=$state("");let owner=$state("");
  function setField(key:"title"|"date"|"attendees"|"summary",value:string):void{meeting.update(data=>{data[key]=value})}
  function toggle(id:number):void{meeting.update(data=>{for(const item of [...data.agenda,...data.actions])if(item.id===id)item.done=!item.done})}
  function updateItem(kind:"agenda"|"decisions",id:number,value:string):void{meeting.update(data=>{const item=data[kind].find(entry=>entry.id===id);if(item)item.text=value})}
  function updateAction(id:number,key:"text"|"owner",value:string):void{meeting.update(data=>{const item=data.actions.find(entry=>entry.id===id);if(item)item[key]=value})}
  function addAction():void{const clean=text.trim();if(!clean)return;meeting.update(data=>{data.actions.push({id:data.nextID,text:clean,owner:owner.trim()||"Unassigned",done:false});data.nextID+=1});text="";owner="";adding=false}
</script>
<main class="meeting" data-slop-selection="none"><header><p>MEETING NOTES</p><input class="title" value={meeting.current.title} aria-label="Meeting title" oninput={(e)=>setField("title",e.currentTarget.value)}/><div><input value={meeting.current.date} placeholder="Date" aria-label="Meeting date" oninput={(e)=>setField("date",e.currentTarget.value)}/><input value={meeting.current.attendees} placeholder="Attendees" aria-label="Attendees" oninput={(e)=>setField("attendees",e.currentTarget.value)}/></div></header><Tabs.Root bind:value={tab}><Tabs.List class="tabs"><Tabs.Trigger value="notes">Record</Tabs.Trigger><Tabs.Trigger value="actions">Actions <span>{meeting.current.actions.filter(item=>!item.done).length}</span></Tabs.Trigger></Tabs.List><Tabs.Content value="notes" class="page"><section class="summary"><label>Working summary<textarea value={meeting.current.summary} oninput={(e)=>setField("summary",e.currentTarget.value)}></textarea></label></section><div class="columns"><section><h2>Agenda</h2><ol>{#each meeting.current.agenda as item,index (item.id)}<li class:done={item.done}><button onclick={()=>toggle(item.id)} aria-label={item.done?"Reopen item":"Complete item"}>{#if item.done}<Check/>{:else}{index+1}{/if}</button><input aria-label="Agenda item" value={item.text} oninput={(e)=>updateItem("agenda",item.id,e.currentTarget.value)}/></li>{/each}</ol></section><section><h2>Decisions</h2><ul>{#each meeting.current.decisions as item}<li><input aria-label="Decision" value={item.text} oninput={(e)=>updateItem("decisions",item.id,e.currentTarget.value)}/></li>{/each}</ul></section></div></Tabs.Content><Tabs.Content value="actions" class="page actions"><div class="action-head"><div><span>NEXT MOVES</span><h2>Action list</h2></div><button onclick={()=>adding=true}><Plus/>Add action</button></div><ol>{#each meeting.current.actions as item (item.id)}<li class:done={item.done}><button onclick={()=>toggle(item.id)} aria-label={item.done?"Reopen action":"Complete action"}>{#if item.done}<Check/>{/if}</button><div><input class="action-text" aria-label="Action" value={item.text} oninput={(e)=>updateAction(item.id,"text",e.currentTarget.value)}/><input class="action-owner" aria-label="Owner" value={item.owner} oninput={(e)=>updateAction(item.id,"owner",e.currentTarget.value)}/></div></li>{/each}</ol></Tabs.Content></Tabs.Root><footer><span>{meeting.current.actions.filter(item=>!item.done).length} open actions</span><span>Decide · assign · leave</span></footer>
<Dialog.Root bind:open={adding}><Dialog.Portal><Dialog.Overlay class="overlay"/><Dialog.Content class="dialog"><form onsubmit={(event)=>{event.preventDefault();addAction()}}><p>NEW COMMITMENT</p><Dialog.Title>Who owns what?</Dialog.Title><label>Action<input bind:value={text} placeholder="Write the outcome"/></label><label>Owner<input bind:value={owner} placeholder="Name or role"/></label><div><Dialog.Close type="button">Cancel</Dialog.Close><button type="submit">Add action</button></div></form><Dialog.Close class="close" aria-label="Close"><X/></Dialog.Close></Dialog.Content></Dialog.Portal></Dialog.Root></main>
